Given the head of a singly linked list, determine the length of the cycle (loop) if one exists. A cycle occurs when a node's next pointer points to a previously visited node in the list. If no cycle is present, return 0.Examples:Input:  Output: 3Explanation: There exists a loop in the linked list and the length of the loop is 3. Input:  Output: 0Explanation: There is no loop present in the Linked List.Try It YourselfTable of Content[Naive Approach] Using Set - O(n) Time and O(n) Space [Expected Approach] Using Floyd’s Cycle Detection Algorithm - O(n) Time and O(1) Space[Naive Approach] Using Set - O(n) Time and O(n) Space The idea is to maintain a set to keep track of visited nodes so far. If the node is not present in set we will insert and move to another node, else we will maintain a counter from that node and will start traversing until we reach to it again by incrementing the counter variable every time.
            C++

    #include <iostream>
#include<unordered_set>
using namespace std;

// Node structure
class Node {
public:
    int data;
    Node* next;
	Node(int x) {
     	data = x;
      	next = nullptr;
    }
};

int lengthOfLoop(Node* head) {

    unordered_set<Node*> visited;
    Node* current = head;
    int count = 0;

    while (current != nullptr) {

        // if the node is already visited, 
      	// it means there is a loop
        if (visited.find(current) != visited.end()) {
            Node* startOfLoop = current;
            do {
                count++;
                current = current->next;
            } while (current != startOfLoop);
            return count;
        }

        // mark the current node as visited
        visited.insert(current);

        // move to the next node
        current = current->next;
    }

    return 0;
}

int main() {

  	Node* head = new Node(25);
    head->next = new Node(14);
    head->next->next = new Node(19);
    head->next->next->next = new Node(33);
    head->next->next->next->next = new Node(10);

    head->next->next->next->next->next = head->next->next;

    cout << lengthOfLoop(head) << endl;

    return 0;
}


